<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;display=swap');

        body {
            margin: 0;
            padding: 0;
            font-family: 'Times New Roman', serif;
            line-height: 1.3;
            color: #000;
            background: #fff;
        }

        .document {
            max-width: 800px;
            margin: 40px auto;
            padding: 40px 50px;
            box-sizing: border-box;
            border: 2px solid #000;
            background: #fff;
            position: relative;
        }

        /* Columns */
        .columns {
            display: flex;
            gap: 40px;
            margin-bottom: 20px;
        }

        .column {
            flex: 1;
            position: relative;
        }

        .column h1 {
            font-size: 28px;
            text-align: center;
            margin-bottom: 20px;
            font-weight: 700;
            border-bottom: 1px solid #000;
            padding-bottom: 10px;
        }

        /* Text blocks with relative positioning */
        .text-block {
            margin-bottom: 15px;
            position: relative;
        }

        .text-block p {
            margin: 8px 0;
            text-indent: 20px;
        }

        .text-block p:first-of-type {
            text-indent: 0;
        }

        /* Placeholder for non-text elements */
        .placeholder {
            width: 100%;
            height: 200px;
            border: 1px dashed #999;
            background: #f9f9f9;
            margin: 20px 0;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            color: #666;
            text-align: center;
            overflow: hidden;
        }

        .placeholder::before {
            content: attr(data-caption);
            font-style: italic;
        }

        .placeholder img-placeholder {
            width: 100%;
            height: 100%;
            object-fit: contain;
            display: none;
        }

        /* Lists */
        ul, ol {
            margin-left: 30px;
            margin-top: 10px;
            margin-bottom: 10px;
        }

        li {
            margin-bottom: 5px;
        }

        /* Small elements like checkboxes */
        .checkbox-group {
            display: inline-block;
            margin-right: 15px;
        }

        .checkbox {
            margin-right: 5px;
        }

        /* Table */
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }

        th, td {
            border: 1px solid #000;
            padding: 8px;
            text-align: left;
        }

        th {
            font-weight: 700;
        }

        /* Signature / line */
        .signature-line {
            width: 300px;
            border-top: 1px solid #000;
            margin: 40px 0 0 20px;
            display: inline-block;
        }

        /* Footer */
        .footer {
            margin-top: 50px;
            font-size: 12px;
            text-align: center;
            color: #666;
        }
    </style>
</head>
<body>
    <div class="document">

        <!-- Title -->
        <div class="text-block">
            <h1>Sample Document Title</h1>
        </div>

        <!-- Paragraphs -->
        <div class="text-block">
            <p>This is the first paragraph in the document. It demonstrates how text flows in the original layout with proper indentation.</p>
        </div>

        <div class="text-block">
            <p>Here is another paragraph with the expected spacing between blocks to match the physical document.</p>
        </div>

        <!-- Multi-column example -->
        <div class="columns">
            <div class="column">
                <div class="text-block">
                    <p>Column 1 - Top text block.</p>
                </div>
                <div class="text-block">
                    <p>Column 1 - Middle paragraph.</p>
                </div>
            </div>
            <div class="column">
                <div class="text-block">
                    <p>Column 2 - Starting from the top.</p>
                </div>
            </div>
        </div>

        <!-- Lists -->
        <div class="text-block">
            <p>Here are some lists as they appear:</p>
            <ul>
                <li>First bullet point in the list</li>
                <li>Second item with additional text if needed</li>
                <li>Third item</li>
            </ul>

            <p>And an ordered list:</p>
            <ol>
                <li>Step one</li>
                <li>Step two</li>
                <li>Step three</li>
            </ol>
        </div>

        <!-- Table -->
        <div class="text-block">
            <table>
                <tr>
                    <th>Header 1</th>
                    <th>Header 2</th>
                </tr>
                <tr>
                    <td>Data row 1</td>
                    <td>Data row 1 col 2</td>
                </tr>
                <tr>
                    <td>Data row 2</td>
                    <td>Data row 2 col 2</td>
                </tr>
            </table>
        </div>

        <!-- Placeholder for image/chart -->
        <div class="text-block">
            <div class="placeholder" data-caption="[Image: Centered placeholder]" style="width: 500px; height: 300px; margin: 30px auto;">
                [Placeholder: Photograph or diagram here]
            </div>
        </div>

        <!-- Checkbox example -->
        <div class="text-block">
            <p>Checkboxes as they appear in the layout:</p>
            <div style="margin-top: 15px;">
                <input type="checkbox" class="checkbox" checked> Option A<br>
                <input type="checkbox" class="checkbox"> Option B<br>
                <input type="checkbox" class="checkbox"> Option C
            </div>
        </div>

        <!-- Signature line -->
        <div class="text-block" style="text-align: right;">
            <p>Signature:</p>
            <div class="signature-line"></div>
        </div>

        <!-- Footer -->
        <div class="footer">
            Page 1 of 1 • Document ID: SAMPLE-001
        </div>

    </div>

    <script>
        // Ensure MathJax renders any potential math in the document
        MathJax.typeset();
    </script>
</body>
</html>
